INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('pricing-specialist', 'Pricing Specialist', 'marketing', '["pricing analyst","pricing manager","cenový analytik","cenová analytička","specialista pricingu","pricing specialista","specialista cenotvorby","revenue management analyst","cenotvorba"]', 'makers', '[{"id":"mh-pricing-role-history","title":"Pricing role history","text":"Held a named pricing, revenue management or category pricing role at a verifiable company","accepted_evidence":["job history","company page","profile"]},{"id":"mh-pricing-analysis-published","title":"Published pricing analysis","text":"Has a public case study, article or talk on a pricing change, price test or elasticity analysis","accepted_evidence":["case study","published article","talk"]},{"id":"mh-pricing-tooling","title":"Pricing tooling and data","text":"Public profile or work names the tools used, e.g. SQL, Excel, Power BI, a repricing or price-monitoring platform","accepted_evidence":["profile","certification","case study"]},{"id":"mh-pricing-results","title":"Measured pricing results","text":"Public example ties a pricing decision to a measured margin, conversion or revenue outcome","accepted_evidence":["case study","talk","published article"]}]', '{"steps":["linkedin_profile","personal_site_crawl","talks_serp","github_profile","x_profile"],"sites":["linkedin.com","medium.com","marketingjournal.cz","ecommercebridge.cz"]}', '2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('sales-development-representative', 'Sales Development Representative', 'sales', '["sdr","bdr","business development representative","junior obchodník","asistent/ka pro obchodní zástupce","appointment setter"]', 'track-record', '[{"id":"mh-outbound-b2b","title":"Outbound B2B prospecting","text":"Held an SDR/BDR or outbound prospecting role at a named B2B company","accepted_evidence":["job history","company page","LinkedIn recommendation"]},{"id":"mh-sales-tooling","title":"Sales tooling","text":"Names sales tools used (Salesforce, HubSpot, Outreach, Apollo, Sales Navigator) in a profile or post","accepted_evidence":["LinkedIn profile","certification listing","personal site"]},{"id":"mh-progression","title":"Role progression","text":"Shows promotion or a move toward AE or team lead at the same or a later employer","accepted_evidence":["job history","LinkedIn post","company announcement"]},{"id":"mh-stated-results","title":"Publicly stated results","text":"States meetings booked or pipeline outcomes publicly (profile, post, talk)","accepted_evidence":["LinkedIn profile","LinkedIn post","podcast"]}]', '{"steps":["linkedin_profile","talks_serp","x_profile","personal_site_crawl"],"sites":["linkedin.com","trailblazer.me","hubspot.com","pavilion.com"]}', '2026-10-09T00:00:00Z');
