INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('doctoral-researcher', 'Doctoral Researcher (PhD / Postdoc)', 'other', '["phd","ph.d.","phd student","phd candidate","doktorand","doktorandka","doctoral researcher","doctoral student","postdoc","post-doc","postdoctoral researcher","postdoctoral fellow","research fellow","vědecký pracovník","výzkumný pracovník"]', 'credentialed', '[{"id":"mh-degree-and-field","title":"Degree and field","text":"Lists a master''s or doctoral degree in the advertised field from a named university","accepted_evidence":["job history","publication","certification listing"]},{"id":"mh-peer-reviewed-output","title":"Peer-reviewed output","text":"Papers or preprints under their name in OpenAlex, ORCID, arXiv or a conference","accepted_evidence":["publication","register entry"]},{"id":"mh-research-group","title":"Research group","text":"Listed on a named lab, institute or research group page","accepted_evidence":["job history","publication"]},{"id":"mh-research-code","title":"Research code or data","text":"Public repositories, models or datasets attached to their research","accepted_evidence":["repo","publication"]},{"id":"mh-talks-and-posters","title":"Talks and posters","text":"Presentations, posters or thesis defence visible on conference or university pages","accepted_evidence":["conference bio","publication"]}]', '{"steps":["orcid_search","openalex_author","github_profile","linkedin_profile","huggingface_profile","talks_serp"],"sites":["orcid.org","scholar.google.com","arxiv.org","researchgate.net","linkedin.com"]}', '2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('psychologist-psychotherapist', 'Psychologist / Psychotherapist', 'other', '["psycholog","psycholožka","psychoterapeut","psychoterapeutka","psycholog/psychoterapeut","psychologist","psychotherapist","klinický psycholog","školní psycholog","pracovní psycholog"]', 'credentialed', '[{"id":"mh-psychology-degree","title":"Psychology degree","text":"Lists a master''s degree in psychology or an accredited psychotherapy training","accepted_evidence":["certification listing","job history","register entry"]},{"id":"mh-therapist-register","title":"Professional register","text":"Listed in a professional register such as ČAP, ČMPS or a clinical psychologist licence","accepted_evidence":["register entry","certification listing"]},{"id":"mh-practice-affiliation","title":"Practice affiliation","text":"Listed on a named clinic, counselling centre, school or company staff page","accepted_evidence":["job history","company filing"]},{"id":"mh-professional-output","title":"Professional output","text":"Articles, talks, podcasts or research on their field under their name","accepted_evidence":["publication","conference bio","press mention"]}]', '{"steps":["linkedin_profile","personal_site_crawl","openalex_author","orcid_search","talks_serp"],"sites":["czap.cz","linkedin.com","researchgate.net","orcid.org"]}', '2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('dental-hygienist', 'Dental Hygienist', 'other', '["dentální hygienistka","dentální hygienista","dentální hygienistka/hygienista","dentální hygienistka/ta","zubní hygienistka"]', 'credentialed', '[{"id":"mh-hygienist-qualification","title":"Hygienist qualification","text":"Holds a listed dental hygiene diploma or bachelor''s degree from a named school","accepted_evidence":["certification listing","job history"]},{"id":"mh-dental-practice-history","title":"Practice history","text":"Listed on a named dental clinic or practice team page","accepted_evidence":["job history","company filing"]},{"id":"mh-hygienist-association","title":"Association membership","text":"Member of the Czech dental hygienists'' association (ASK DH) or a foreign equivalent","accepted_evidence":["register entry","certification listing"]},{"id":"mh-continuing-education","title":"Continuing education","text":"Named courses, congresses or certifications in dental hygiene or periodontology","accepted_evidence":["certification listing","conference bio"]}]', '{"steps":["linkedin_profile","personal_site_crawl","instagram_profile","talks_serp"],"sites":["asociacedh.cz","linkedin.com","jobs.cz","instagram.com"]}', '2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('physiotherapist', 'Physiotherapist', 'other', '["fyzioterapeut","fyzioterapeutka","fyzioterapeut/ka","physical therapist","lymfoterapeut","lymfoterapeut/ka","rehabilitační pracovník"]', 'credentialed', '[{"id":"mh-physio-qualification","title":"Physiotherapy qualification","text":"Holds a listed physiotherapy degree from a named faculty or college","accepted_evidence":["certification listing","job history"]},{"id":"mh-physio-register","title":"Professional register","text":"Listed in the UNIFY ČR register or holds a Ministry of Health practice certificate","accepted_evidence":["register entry","certification listing"]},{"id":"mh-physio-practice-history","title":"Practice history","text":"Worked at named rehabilitation centres, clinics, spas or sports clubs","accepted_evidence":["job history","company filing"]},{"id":"mh-physio-methods","title":"Certified methods","text":"Named method certifications such as DNS, Bobath, McKenzie or lymphatic drainage","accepted_evidence":["certification listing","conference bio"]}]', '{"steps":["linkedin_profile","personal_site_crawl","instagram_profile","talks_serp","openalex_author"],"sites":["unify-cr.cz","linkedin.com","jobs.cz","researchgate.net"]}', '2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('social-worker', 'Social Worker', 'other', '["sociální pracovník","sociální pracovnice","sociální pracovník/pracovnice","pracovník v sociálních službách","pracovnice v sociálních službách","pečovatel","pečovatelka","case worker"]', 'credentialed', '[{"id":"mh-social-work-qualification","title":"Social work qualification","text":"Holds a qualification under Act 108/2006 (social work degree or accredited course) listed publicly","accepted_evidence":["certification listing","job history"]},{"id":"mh-provider-history","title":"Provider history","text":"Worked at named registered social service providers, NGOs or municipal offices","accepted_evidence":["job history","company filing","register entry"]},{"id":"mh-service-area","title":"Service area","text":"States a service area such as debt counselling, family support or elder care in a profile","accepted_evidence":["job history","publication"]},{"id":"mh-professional-output","title":"Professional output","text":"Talks, articles, projects or grants attributed to them in the social sector","accepted_evidence":["publication","conference bio","press mention"]}]', '{"steps":["linkedin_profile","personal_site_crawl","talks_serp"],"sites":["socialnipracovnici.cz","mpsv.cz","linkedin.com","jobs.cz"]}', '2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO role_templates (key, title, family, aliases_json, profile, must_haves_json, sources_json, created_at) VALUES ('trust-safety-investigator', 'Trust & Safety Investigator', 'other', '["abuse investigator","trust and safety analyst","trust & safety analyst","trust and safety specialist","trust & safety specialist","fraud investigator","risk investigator","platform integrity analyst"]', 'verify-only', '[{"id":"mh-investigations-history","title":"Investigations history","text":"Held fraud, abuse, risk or trust & safety roles at named platforms or payment companies","accepted_evidence":["job history","company filing"]},{"id":"mh-case-tooling","title":"Case tooling","text":"Names SQL, case-management or link-analysis tools used in investigations","accepted_evidence":["job history","certification listing"]},{"id":"mh-fraud-domain-knowledge","title":"Domain knowledge","text":"Talks, posts or certifications on fraud patterns, AML or platform abuse","accepted_evidence":["publication","conference bio","certification listing"]},{"id":"mh-policy-work","title":"Policy work","text":"Contributed to public policy pages, enforcement guidelines or transparency reports","accepted_evidence":["publication","company filing"]}]', '{"steps":["linkedin_profile","talks_serp","x_profile","personal_site_crawl"],"sites":["linkedin.com","tspa.org","medium.com","acfe.com"]}', '2026-10-09T00:00:00Z');
